sys_ux_client_script.script:
async function handler({ api, event, helpers, imports }) {
    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or callable.");
        return;
    }

    try {
        // Send the API request
        const response = await helpers.snHttp(
            "/api/985627/value_builder_task",
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({}),
            }
        );

        // Debugging: Log the full response structure
        console.log("Full Response Object:", response);

        // Check for success status
        if (response.status === 200 || (response.response?.result?.status === "success")) {
            console.log("Success: Property updated successfully.", response.result || response);
            alert("Success: Property updated successfully!"); // Add alert on success
        } else {
            console.error(
                "Error: Failed to call Script API. Response data:",
                response.response
            );
        }
    } catch (error) {
        // Handle any errors in the API call
        console.error(`Error calling script:`, error.message || error);
        if (error.response) {
            console.error("Error response:", error.response);
        } else if (error.data) {
            console.error("Error data:", error.data);
        }
    }
}
